(function(window,document){ function iniciarAplicacao(){ if(window.PontoDignoUI)window.PontoDignoUI.inicializarUI(); if(window.PontoDignoFormulario)window.PontoDignoFormulario.configurarFormulario(); if(window.PontoDignoRouter)window.PontoDignoRouter.iniciarRoteador(); } if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",iniciarAplicacao,{once:true});else iniciarAplicacao(); })(window,document);